args.script:
(() => {
  const rows = [...document.querySelectorAll('tr.athing')];
  return rows.slice(0,10).map(row => {
    const titleEl = row.querySelector('.titleline a');
    const sub = row.nextElementSibling?.querySelector('.subtext');
    return {
      id: row.id,
      title: titleEl?.textContent?.trim(),
      url: titleEl?.href,
      points: sub?.querySelector('.score')?.textContent?.trim() || '0 points',
      age: sub?.querySelector('.age')?.textContent?.trim(),
      comments: sub?.querySelector('a:last-child')?.textContent?.trim()
    };
  });
})()

(async () => {
  const html = await fetch('https://news.ycombinator.com/show', {cache: 'no-store'}).then(r => r.text());
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const rows = [...doc.querySelectorAll('tr.athing')];
  return rows.slice(0, 30).map(row => {
    const titleEl = row.querySelector('.titleline a');
    const sub = row.nextElementSibling?.querySelector('.subtext');
    return {
      id: row.id,
      title: titleEl?.textContent?.trim(),
      url: titleEl?.href,
      points: sub?.querySelector('.score')?.textContent?.trim() || '0 points',
      age: sub?.querySelector('.age')?.textContent?.trim(),
      comments: sub?.querySelector('a:last-child')?.textContent?.trim()
    };
  });
})()
